/*
 * The typed entry point for content (server side): one content set per
 * locale, each a `Content` (content/schema.ts), and the image registry the
 * locales share. Pages and server components read it through
 * src/lib/content.ts, which picks the route's locale and runs the build-time
 * count checks on every set.
 *
 *   deck.ts      the four cards: ids, order, identities, paths (no text)
 *   images.ts    image registry (generated by scripts/images/fetch-and-build.mjs)
 *   de/, en/     one content set per locale: site.ts and hand.ts (slim, D7),
 *                cases/*.ts, pages/*.ts, illustrations.ts (server only)
 */
import type { Locale } from '@/lib/i18n'
import { content as de } from './de'
import { content as en } from './en'
import type { Content } from './schema'

export const contents = { de, en } satisfies Record<Locale, Content>

export { images } from './images'
